@six.add_metaclass(ABCMeta)
class ATCommand(object):
    def __init__(self, executor, *args):
        self._executor = executor
        self._verify_args(*args)
        self._args = args

    @abstractmethod
    def _verify_args(self, *args):
        pass

    def _verify_single_integer_arg(self, args, enum_class):
        if len(args) != 1:
            raise ParameterInvalid("{} only allow 1 argument".format(self.name))

        self._verify_integer_arg(args[0], enum_class)

    def _verify_integer_arg(self, arg, enum_class):
        values = self._get_data_class_values(enum_class)
        if arg not in values:
            raise ParameterInvalid("{} only allow {} in {} arg={}".format(
                self.name, enum_class.__name__, ",".join(str(_) for _ in values), arg))

    def _verify_string_arg(self, arg, enum_class):
        values = self._get_data_class_values(enum_class)
        if arg not in values:
            raise ParameterInvalid("{} only allow {} in {}".format(self.name, enum_class.__name__, ",".join(values)))

    def _verify_value_in_list_arg(self, arg, enum_class):
        values = self._get_data_class_values(enum_class)
        list_value = values[0]
        if arg not in list_value:
            stringified_list_value = [str(_) for _ in list_value]
            raise ParameterInvalid("{} only allow {} in {}".format(self.name, enum_class.__name__, ",".join(stringified_list_value)))

    @staticmethod
    def _get_data_class_values(data_class):
        values = []
        for key in data_class.__dict__:
            if key.startswith("_"):
                continue
            # continue when the member is function
            if inspect.ismethod(getattr(data_class, key)):
                continue
            values.append(getattr(data_class, key))
        return values

    def _decorate_string_args_with_double_quotations(self, *args):
        has_single_arg = len(args) == 1

        if has_single_arg and not isinstance(args[0], str):
            return [str(args[0]), ]

        if has_single_arg:
            return [args[0], ] if args[0] == '?' else ['"{}"'.format(args[0])]

        format_args = []
        for arg in args:
            if arg is None:
                format_args.append('')
            elif isinstance(arg, str):
                format_args.append('"{}"'.format(arg))
            else:
                format_args.append(str(arg))
        return format_args

    def _execute(self, *args, **kwargs):
        self._verify_args(*args)

        format_args = self._decorate_string_args_with_double_quotations(*args)
        args_str = ",".join(format_args)
        cmd = "{}={}".format(self.name, args_str)
        output = self._executor.execute(cmd)
        logging.info('AT command `{}` return `{}`'.format(cmd, output))
        self._check_output(output)
        return output

    def _check_output(self, output):
        pass

    def execute(self):
        logging.info('AT command input parameters: {}'.format(self._args))
        return self._execute(*self._args)

    @property
    def name(self):
        return "AT+" + self.__class__.__name__


