class EAPNACT(ATCommand):

    class PDPContextActivation(object):
        DEACTIVATED = 0
        ACTIVATED = 1

    class ApnType(object):
        UNKNOWN = "unknown"
        DEFAULT = "default"
        IMS = "ims"
        MMS = "mms"
        SUPL = "supl"
        DUN = "dun"
        HIPRI = "hipri"
        FOTA = "fota"
        CBS = "cbs"
        EMERGENCY = "emergency"
        IA = "ia"
        DM = "dm"
        WAP = "wap"
        NET = "net"
        CMMAIL = "cmmail"
        TETHERING = "tethering"
        RCSE = "rcse"
        XCAP = "xcap"
        RCS = "rcs"

    def __init__(self, executor, *args):
        super(EAPNACT, self).__init__(executor, *args)

    def _verify_args(self, *args):
        arg_len = len(args)
        if arg_len not in [2, 3, 4]:
            raise ParameterInvalid("{} only allow 2 3 or 4 arguments".format(self.name))

        pdp_context_activation = 0
