class CGDCONT(ATCommand):
    QUESTION_MARK = '?'

    class PDPType(object):
        IP = 'IP'
        IPV6 = 'IPV6'
        IPV4V6 = 'IPV4V6'
        ETHERNET = 'Ethernet'
        UNSTRUCTURED = 'Unstructured'

    def __init__(self, executor, *args):
        super(CGDCONT, self).__init__(executor, *args)

    def _verify_args(self, *args):
        if len(args) == 3:
            self._verify_string_arg(args[1], CGDCONT.PDPType)
            return
        if len(args) != 1 or args[0] != self.QUESTION_MARK:
            msg = "{} allow 3 arguments or 1 argument {}".format(self.name, self.QUESTION_MARK)
            raise ParameterInvalid(msg)

    def _execute(self, *args, **kwargs):
        if len(args) != 1:
            return super(CGDCONT, self)._execute(*args, **kwargs)
        else:
            self._verify_args(*args)
            format_args = self._decorate_string_args_with_double_quotations(*args)
            args_str = ",".join(format_args)
            cmd = "{}{}".format(self.name, args_str)
            output = self._executor.execute(cmd)
            logging.info('AT command `{}` return `{}`'.format(cmd, output))
            self._check_output(output)
            return output


