class ATD(ATCommand):

    def __init__(self, executor, *args):
        super(ATD, self).__init__(executor, *args)

    def _verify_args(self, *args):
        if len(args) != 1:
            raise ParameterInvalid("parameters length {} invalid".format(len(args)))

        # support multiple call number: '0105', '911', '+6688'
        escape_call_number = args[0].lstrip('+')
        if not re.match(r"\d+", escape_call_number):
            raise ParameterInvalid("call number '{}' invalid".format(args[0]))

    @staticmethod
    def _decorate_call_number(call_number):
        if str(call_number) == "911":
            return "E911"
        return "{}".format(call_number)

    def _execute(self, *args, **kwargs):
        self._verify_args(*args)
        call_number = args[0]
        formated_call_number = self._decorate_call_number(call_number)
        output = self._executor.execute("{}{};".format(self.name, formated_call_number))
        return output

    @property
    def name(self):
        return self.__class__.__name__


