class CEDRXS(ATCommand):

    class Mode(object):
        DISABLE_EDRX = 0
        ENABLE_EDRX = 1
        ENABLE_EDRX_AND_UNSOLICITED_RESULT_CODE = 2
        DISABLE_EDRX_AND_REST_TO_MANUFACTURER_DEFAULT = 3

    class ACTType(object):
        NOT_USING_EDRX = 0
        EC_GSM_IOT_A_GB = 1
        GSM_A_GB = 2
        UTRAN_IU = 3
        E_UTRAN_WB_S1 = 4
        E_UTRAN_NB_S1 = 5
        SATELLITE_E_UTRAN_NB_S1 = 6
        SATELLITE_E_UTRAN_WB_S1 = 7
        NG_RAN_N1 = 8
        SATELLITE_NG_RAN_N1 = 9

    class NRCircleDuration(object):
        _seconds_vs_bits = {256: "0000", 512: "0001", 1024: "0010", 2048: "0011", 4096: "0100", 8192: "0101",
                            16384: "0110", 32768: "0111", 65536: "1000", 131072: "1001", 262144: "1010", 524288: "1011",
                            1048576: "1100"}
        _bits_vs_seconds = {v: k for k, v in _seconds_vs_bits.items()}

        @classmethod
        def get_bits_from_seconds(cls, seconds):
            try:
                return cls._seconds_vs_bits[seconds]
            except KeyError:
                raise ParameterInvalid("Invalid seconds value: {}, seconds must be in {}".
                                       format(seconds, list(cls._seconds_vs_bits.keys())))

        @classmethod
        def get_seconds_from_bits(cls, bits):
            return cls._bits_vs_seconds[bits]

        values = [value for value in _seconds_vs_bits.values()]  # noqa: C416

    class ExtendedPagingTimeWindow(object):
        _seconds_vs_bits = {128: "0000", 256: "0001", 384: "0010", 512: "0011", 640: "0100", 768: "0101", 896: "0110",
                            1024: "0111", 1152: "1000", 1280: "1001", 1408: "1010", 1536: "1011", 1664: "1100",
                            1792: "1101", 1920: "1110", 2048: "1111", 2176: "00010000", 2304: "00010001",
                            2432: "00010010", 2560: "00010011", 2688: "00010100", 2816: "00010101", 2944: "00010110",
                            3072: "00010111", 3200: "00011000", 3328: "00011001", 3456: "00011010", 3584: "00011011",
                            3712: "00011100", 3840: "00011101", 3968: "00011110", 4096: "00011111"}
        _bits_vs_seconds = {v: k for k, v in _seconds_vs_bits.items()}
        values = [value for value in _seconds_vs_bits.values()]  # noqa: C416

        @classmethod
        def get_bits_from_seconds(cls, seconds):
            try:
                return cls._seconds_vs_bits[seconds]
            except KeyError:
                raise ParameterInvalid("Invalid seconds value: {}, seconds must be in {}".
                                       format(seconds, list(cls._seconds_vs_bits.keys())))

        @classmethod
        def get_seconds_from_bits(cls, bits):
            return cls._bits_vs_seconds[bits]

    def __init__(self, executor, *args):
        super(CEDRXS, self).__init__(executor, *args)

    def _verify_args(self, *args):
        self._verify_integer_arg(args[0], CEDRXS.Mode)
        self._verify_integer_arg(args[1], CEDRXS.ACTType)
        self._verify_value_in_list_arg(args[2], CEDRXS.NRCircleDuration)
        self._verify_value_in_list_arg(args[3], CEDRXS.ExtendedPagingTimeWindow)
